## Dynamic Range Versions

The key shift is replacing `A2:A421` with `A2:A` (open-ended). Sheets evaluates only populated cells in COUNTIF/COUNTIFS with open ranges, so this is safe and won't drag in thousands of blank rows.

---

### Summary Panel — Dynamic Formulas

```
Total responses:      =COUNTA(Raw!A2:A)
Flagged REVIEW:       =COUNTIF(Raw!P2:P,"REVIEW")
Final rows:           =COUNTIFS(Raw!P2:P,"OK",Raw!O2:O,"")
```

Safer unique volunteers (excludes blank emails):
```
=SUMPRODUCT(
  (Raw!C2:C<>"")*
  (Raw!P2:P="OK")*
  (Raw!O2:O="")/
  IF(COUNTIFS(Raw!C2:C,Raw!C2:C,Raw!P2:P,"OK",Raw!O2:O,"")=0,
     1,
     COUNTIFS(Raw!C2:C,Raw!C2:C,Raw!P2:P,"OK",Raw!O2:O,"")))
```
This counts unique emails among accepted, non-superseded rows only, and skips blanks cleanly.

Joined Before % (accepted rows only):
```
=COUNTIFS(Raw!G2:G,"Yes",Raw!P2:P,"OK",Raw!O2:O,"")
/COUNTIFS(Raw!P2:P,"OK",Raw!O2:O,"")
```

Park counts (put canonical name in D column, formula in E):
```
=COUNTIFS(Raw!J2:J,D2,Raw!P2:P,"OK",Raw!O2:O,"")
```

---

### Final Sheet — Header + A:F Only

In `Final!A1`, paste the header manually or use:
```
=Raw!A1:F1
```
This spills across A1:F1 automatically.

In `Final!A2`, paste:
```
=IFERROR(
  FILTER(Raw!A2:F,
         Raw!P2:P="OK",
         Raw!O2:O=""),
  "No accepted rows yet.")
```
Pulling `A2:F` (no column limit on F) gives you exactly the six original columns. FILTER stops at the last populated row, so it stays dynamic without dragging anything.

---

### On Performance: When to Switch to Apps Script

Sheets formulas with open-ended ranges on 500–1000 rows are usually fine, with one exception: `SUMPRODUCT` with multiple `COUNTIFS` inside it (like the unique-volunteers formula) recalculates on every edit anywhere in the sheet, and can get sluggish around 800+ rows. If you notice lag, the script below replaces the entire Summary panel on demand rather than recalculating live.

```javascript
function buildSummary() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName("Raw");
  const summary = ss.getSheetByName("Summary");

  // Read raw data starting at row 2 (skip header)
  const data = raw.getRange(2, 1, raw.getLastRow() - 1, 16).getValues();
  // Columns (0-indexed): C=2 email, G=6 joinedBefore, J=9 park, O=14 superseded, P=15 flag

  let total = 0, reviewCount = 0, finalCount = 0;
  const emails = new Set();
  const parks = {};
  let joinedYes = 0, joinedTotal = 0;

  for (const row of data) {
    if (!row[0]) continue;          // skip empty rows
    total++;

    const flag = String(row[15]).trim();
    const superseded = String(row[14]).trim();
    const email = String(row[2]).trim().toLowerCase();
    const joined = String(row[6]).trim();
    const park = String(row[9]).trim();

    if (flag === "REVIEW") reviewCount++;

    if (flag === "OK" && superseded === "") {
      finalCount++;
      if (email) emails.add(email);
      if (joined === "Yes") joinedYes++;
      joinedTotal++;
      if (park && park !== "REVIEW") {
        parks[park] = (parks[park] || 0) + 1;
      }
    }
  }

  const pctJoined = joinedTotal > 0
    ? (joinedYes / joinedTotal * 100).toFixed(1) + "%"
    : "N/A";

  // Build output rows
  const out = [
    ["Metric", "Value"],
    ["Total responses", total],
    ["Flagged REVIEW", reviewCount],
    ["Final rows (accepted)", finalCount],
    ["Unique volunteers (by email)", emails.size],
    ["Joined Before % (accepted)", pctJoined],
    [],
    ["Park", "Count"],
    ...Object.entries(parks).sort((a, b) => b[1] - a[1])
  ];

  // Write to Summary sheet, clearing old content first
  summary.clearContents();
  summary.getRange(1, 1, out.length, 2).setValues(out);
  SpreadsheetApp.getUi().alert("Summary updated.");
}
```

To use it: open **Extensions > Apps Script**, paste this in, save, then run `buildSummary`. You can also add a button on the Summary sheet (**Insert > Drawing**, then assign the script) so anyone can refresh it with one click without opening the script editor.

The script writes static values, so it won't slow down your sheet at all between runs. For a sheet that gets new responses weekly, running it manually is plenty. If responses come in continuously, you could add a time-based trigger under **Triggers** in the Apps Script editor to run it nightly.

```javascript
function runCleanPipeline() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName("Raw");

  if (!raw) {
    SpreadsheetApp.getUi().alert("Sheet named 'Raw' not found.");
    return;
  }

  markSuperseded(raw);
  buildFinal(ss, raw);

  SpreadsheetApp.getUi().alert("Done — superseded rows marked and Final sheet updated.");
}

// ── 1. Mark superseded rows in Raw!O ─────────────────────────────────────────

function markSuperseded(raw) {
  const lastRow = raw.getLastRow();
  if (lastRow < 2) return;

  const numRows = lastRow - 1;

  // Read timestamps (col A), emails (col C), and current O values in one batch
  const timestamps = raw.getRange(2, 1, numRows, 1).getValues();   // A2:A
  const emails     = raw.getRange(2, 3, numRows, 1).getValues();   // C2:C
  const oCol       = raw.getRange(2, 15, numRows, 1).getValues();  // O2:O

  // Build a map: normalised email → { bestRowIndex, bestTimestamp }
  // "bestRowIndex" is the index into our arrays (0-based, so raw row = index + 2)
  const best = {};

  for (let i = 0; i < numRows; i++) {
    const email = String(emails[i][0]).trim().toLowerCase();
    if (!email) continue;

    const ts = timestamps[i][0];
    const tsValue = ts instanceof Date ? ts.getTime() : new Date(ts).getTime();
    if (isNaN(tsValue)) continue;

    if (!best[email] || tsValue > best[email].ts) {
      best[email] = { index: i, ts: tsValue };
    }
  }

  // Build updated O column: set "SUPERSEDED" on non-best duplicates,
  // clear it on the best row (in case a previous run marked it wrongly),
  // leave rows with blank email untouched.
  const newO = oCol.map((cell, i) => {
    const email = String(emails[i][0]).trim().toLowerCase();
    if (!email) return [cell[0]];                      // blank email — no change
    if (best[email].index === i) return [""];          // best row — ensure not marked
    return ["SUPERSEDED"];                             // older duplicate
  });

  raw.getRange(2, 15, numRows, 1).setValues(newO);
}

// ── 2. Build / refresh the Final sheet ───────────────────────────────────────

function buildFinal(ss, raw) {
  const lastRow = raw.getLastRow();
  if (lastRow < 2) return;

  const numRows = lastRow - 1;

  // Read everything we need in two batches
  const sourceData = raw.getRange(2, 1, numRows, 6).getValues();   // A:F
  const flags      = raw.getRange(2, 15, numRows, 2).getValues();  // O:P (cols 15–16)

  // Filter to accepted rows
  const accepted = sourceData.filter((_, i) => {
    const superseded = String(flags[i][0]).trim();   // col O
    const flag       = String(flags[i][1]).trim();   // col P
    return flag === "OK" && superseded === "";
  });

  // Get or create Final sheet
  let final = ss.getSheetByName("Final");
  if (!final) {
    final = ss.insertSheet("Final");
  } else {
    final.clearContents();
  }

  // Write header from Raw!A1:F1
  const header = raw.getRange(1, 1, 1, 6).getValues();
  final.getRange(1, 1, 1, 6).setValues(header);

  // Write accepted rows (if any)
  if (accepted.length > 0) {
    final.getRange(2, 1, accepted.length, 6).setValues(accepted);
  }
}

// ── 3. Custom menu ────────────────────────────────────────────────────────────

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("Volunteer Data")
    .addItem("Refresh Final + Mark Superseded", "runCleanPipeline")
    .toUi();
}
```

---

### How to install and use it

Paste the whole thing into **Extensions > Apps Script**, replacing any existing code. Save with Ctrl+S, then reload your spreadsheet — you'll see a **Volunteer Data** menu appear in the menu bar. Click **Refresh Final + Mark Superseded** to run it any time.

If you want it to run automatically when new form responses arrive, go to **Extensions > Apps Script > Triggers** (the clock icon on the left), add a trigger for `runCleanPipeline`, and set the event type to "On form submit."

---

### What it does and why

A few decisions worth knowing about:

**Single read per column range.** Both functions read their data in one or two `getValues()` calls and work on plain JavaScript arrays, then write back in a single `setValues()`. This is the main performance pattern for Apps Script — the slowdown in scripts almost always comes from calling `getValue()` or `setValue()` inside a loop, which makes a separate API call per cell. At 1000 rows you should see this finish in under three seconds.

**markSuperseded is non-destructive for blank emails.** Rows with no email are left exactly as they were in column O, so your existing REVIEW flags there aren't touched.

**markSuperseded is also self-correcting.** If a previously superseded row somehow becomes the most recent (e.g., you delete a newer duplicate manually), the script clears the SUPERSEDED flag on it rather than leaving stale data.

**buildFinal always clears first.** This means re-running is safe — you won't accumulate duplicate rows in Final if you run the script multiple times.

The one thing to verify before first use: confirm your O and P columns are actually columns 15 and 16 (the script uses 1-based column numbers). If you added or removed any helper columns, adjust the `15` and `16` values in the `getRange` calls inside `buildFinal`, and the `15` in `markSuperseded`, to match your actual layout.

```javascript
// Column indices (1-based for getRange, 0-based for array access)
const COL = {
  TIMESTAMP:  { r: 1,  a: 0  },  // A
  NAME:       { r: 2,  a: 1  },  // B
  EMAIL:      { r: 3,  a: 2  },  // C
  JOINEDBEFORE:{ r: 4, a: 3  },  // D
  PHONE:      { r: 5,  a: 4  },  // E
  PREFERREDPARK:{ r: 6,a: 5  },  // F
  NORMJOINED: { r: 7,  a: 6  },  // G
  NORMPHONE:  { r: 8,  a: 7  },  // H
  NORMTIMESTAMP:{ r: 9,a: 8  },  // I
  CANONPARK:  { r: 10, a: 9  },  // J
  EMAILKEY:   { r: 11, a: 10 },  // K
  NAMEKEY:    { r: 12, a: 11 },  // L
  DUPEMAILFLAG:{ r: 13,a: 12 },  // M
  DUPNAMETIME:{ r: 14, a: 13 },  // N
  SUPERSEDED: { r: 15, a: 14 },  // O
  REVIEW:     { r: 16, a: 15 },  // P
};

// ── Entry point ───────────────────────────────────────────────────────────────

function runCleanPipeline() {
  const ss  = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName("Raw");

  if (!raw) {
    SpreadsheetApp.getUi().alert("Sheet named 'Raw' not found.");
    return;
  }

  markSuperseded(ss, raw);
  buildFinal(ss, raw);

  SpreadsheetApp.getUi().alert("Done — superseded rows marked and Final sheet updated.");
}

// ── 1. Mark superseded rows + write Superseded Log ───────────────────────────

function markSuperseded(ss, raw) {
  const lastRow = raw.getLastRow();
  if (lastRow < 2) return;

  const numRows = lastRow - 1;

  // Read all 16 columns in one batch
  const data = raw.getRange(2, 1, numRows, 16).getValues();

  // ── Find the best (most recent) row per email ──
  // best[email] = { index (0-based), ts (ms) }
  const best = {};

  for (let i = 0; i < numRows; i++) {
    const email = String(data[i][COL.EMAIL.a]).trim().toLowerCase();
    if (!email) continue;

    const raw_ts = data[i][COL.TIMESTAMP.a];
    const ts     = raw_ts instanceof Date ? raw_ts.getTime()
                                          : new Date(raw_ts).getTime();
    if (isNaN(ts)) continue;

    if (!best[email] || ts > best[email].ts) {
      best[email] = { index: i, ts };
    }
  }

  // ── Build updated O column + collect log entries ──
  const newO   = [];
  const logRows = [];   // [email, keptRowNum, supRowNum, keptTs, supTs]

  for (let i = 0; i < numRows; i++) {
    const email    = String(data[i][COL.EMAIL.a]).trim().toLowerCase();
    const current  = data[i][COL.SUPERSEDED.a];

    if (!email) {
      newO.push([current]);   // blank email — leave O untouched
      continue;
    }

    const isBest = best[email].index === i;

    if (isBest) {
      newO.push([""]);        // best row — clear any stale SUPERSEDED
    } else {
      newO.push(["SUPERSEDED"]);

      // Build log entry — raw sheet row numbers are i+2 (1-based, skip header)
      const supRowNum  = i + 2;
      const bestRowNum = best[email].index + 2;
      const supTs      = data[i][COL.TIMESTAMP.a];
      const bestTs     = data[best[email].index][COL.TIMESTAMP.a];

      logRows.push([email, bestRowNum, supRowNum, bestTs, supTs]);
    }
  }

  // Write O column back in one call
  raw.getRange(2, COL.SUPERSEDED.r, numRows, 1).setValues(newO);

  // ── Write Superseded Log sheet ──
  let logSheet = ss.getSheetByName("Superseded Log");
  if (!logSheet) {
    logSheet = ss.insertSheet("Superseded Log");
  } else {
    logSheet.clearContents();
  }

  const logHeader = [["Email", "Kept Row #", "Superseded Row #",
                       "Kept Timestamp", "Superseded Timestamp"]];
  logSheet.getRange(1, 1, 1, 5).setValues(logHeader);

  if (logRows.length > 0) {
    logSheet.getRange(2, 1, logRows.length, 5).setValues(logRows);
  }
}

// ── 2. Build / refresh the Final sheet ───────────────────────────────────────

function buildFinal(ss, raw) {
  const lastRow = raw.getLastRow();
  if (lastRow < 2) return;

  const numRows = lastRow - 1;

  // Read A:F (original columns) and O:P (superseded + review flag) separately
  const sourceData = raw.getRange(2, 1, numRows, 6).getValues();          // A:F
  const opCols     = raw.getRange(2, COL.SUPERSEDED.r, numRows, 2).getValues(); // O:P

  const accepted = sourceData.filter((_, i) => {
    const superseded = String(opCols[i][0]).trim();   // O
    const review     = String(opCols[i][1]).trim();   // P
    return review === "OK" && superseded === "";
  });

  let final = ss.getSheetByName("Final");
  if (!final) {
    final = ss.insertSheet("Final");
  } else {
    final.clearContents();
  }

  // Header from Raw!A1:F1
  const header = raw.getRange(1, 1, 1, 6).getValues();
  final.getRange(1, 1, 1, 6).setValues(header);

  if (accepted.length > 0) {
    final.getRange(2, 1, accepted.length, 6).setValues(accepted);
  }
}

// ── 3. Custom menu ────────────────────────────────────────────────────────────

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("Volunteer Data")
    .addItem("Refresh Final + Mark Superseded", "runCleanPipeline")
    .toUi();
}
```

