### What changed from the previous version

**Column layout is now explicit.** The `COL` object at the top maps every column name to both its 1-based range number and its 0-based array index. If you ever shift columns around, you only need to update that one block — nothing else in the script hardcodes column positions.

**Superseded Log sheet.** Each run clears and rewrites it. The five columns give you enough to audit every decision: you can see which row was kept, which was dropped, and compare the timestamps directly. Timestamps are written as the raw values from column A, so they'll display however your sheet is formatted.

**Blank-email rows in O are genuinely untouched.** The previous version wrote `[current]` back for blank-email rows, which is a no-op write. This version does the same, so the value in O is preserved exactly.

**buildFinal is unchanged in behavior** — it still reads O and P by their column numbers from `COL`, so it stays in sync automatically if you adjust the `COL` block.

One thing to double-check before running: make sure your Raw sheet's header row actually matches the 16-column layout listed in `COL`. If any columns are in a different order, update the `COL` values to match before you run it.

```javascript
// Column indices (1-based for getRange, 0-based for array access)
const COL = {
  TIMESTAMP:    { r: 1,  a: 0  },  // A
  NAME:         { r: 2,  a: 1  },  // B
  EMAIL:        { r: 3,  a: 2  },  // C
  JOINEDBEFORE: { r: 4,  a: 3  },  // D
  PHONE:        { r: 5,  a: 4  },  // E
  PREFERREDPARK:{ r: 6,  a: 5  },  // F
  NORMJOINED:   { r: 7,  a: 6  },  // G
  NORMPHONE:    { r: 8,  a: 7  },  // H
  NORMTIMESTAMP:{ r: 9,  a: 8  },  // I
  CANONPARK:    { r: 10, a: 9  },  // J
  EMAILKEY:     { r: 11, a: 10 },  // K
  NAMEKEY:      { r: 12, a: 11 },  // L
  DUPEMAILFLAG: { r: 13, a: 12 },  // M
  DUPNAMETIME:  { r: 14, a: 13 },  // N
  SUPERSEDED:   { r: 15, a: 14 },  // O
  REVIEW:       { r: 16, a: 15 },  // P
};

const TEN_MINUTES_MS = 10 * 60 * 1000;

// ── Entry point ───────────────────────────────────────────────────────────────

function runCleanPipeline() {
  const ss  = SpreadsheetApp.getActiveSpreadsheet();
  const raw = ss.getSheetByName("Raw");

  if (!raw) {
    SpreadsheetApp.getUi().alert("Sheet named 'Raw' not found.");
    return;
  }

  const emailLogRows = markSuperseded(raw);
  const nameLogRows  = markNameDuplicates(raw);
  buildSupersededLog(ss, emailLogRows, nameLogRows);
  buildFinal(ss, raw);

  SpreadsheetApp.getUi().alert("Done — superseded rows marked and Final sheet updated.");
}

// ── 1. Mark superseded rows by email, return log rows ────────────────────────

function markSuperseded(raw) {
  const lastRow = raw.getLastRow();
  if (lastRow < 2) return [];

  const numRows = lastRow - 1;
  const data    = raw.getRange(2, 1, numRows, 16).getValues();

  // Find best (most recent) row index per email
  const best = {};
  for (let i = 0; i < numRows; i++) {
    const email = String(data[i][COL.EMAIL.a]).trim().toLowerCase();
    if (!email) continue;

    const rawTs = data[i][COL.TIMESTAMP.a];
    const ts    = rawTs instanceof Date ? rawTs.getTime() : new Date(rawTs).getTime();
    if (isNaN(ts)) continue;

    if (!best[email] || ts > best[email].ts) {
      best[email] = { index: i, ts };
    }
  }

  // Build updated O column and collect log entries
  const newO     = [];
  const logRows  = [];

  for (let i = 0; i < numRows; i++) {
    const email   = String(data[i][COL.EMAIL.a]).trim().toLowerCase();
    const current = data[i][COL.SUPERSEDED.a];

    if (!email) {
      newO.push([current]);   // blank email — leave O untouched
      continue;
    }

    if (best[email].index === i) {
      newO.push([""]);        // best row — clear any stale flag
    } else {
      newO.push(["SUPERSEDED"]);

      const supRowNum  = i + 2;
      const bestRowNum = best[email].index + 2;
      const supTs      = data[i][COL.TIMESTAMP.a];
      const bestTs     = data[best[email].index][COL.TIMESTAMP.a];

      logRows.push([email, bestRowNum, supRowNum, bestTs, supTs]);
    }
  }

  raw.getRange(2, COL.SUPERSEDED.r, numRows, 1).setValues(newO);
  return logRows;
}

// ── 2. Mark name-duplicates (blank-email rows only), return log rows ──────────

function markNameDuplicates(raw) {
  const lastRow = raw.getLastRow();
  if (lastRow < 2) return [];

  const numRows = lastRow - 1;
  const data    = raw.getRange(2, 1, numRows, 16).getValues();

  // Collect blank-email rows that have a valid NameKey and NormTimestamp
  // candidatesByName[nameKey] = [ { index, tsMs, normTs } ]
  const candidatesByName = {};

  for (let i = 0; i < numRows; i++) {
    const email   = String(data[i][COL.EMAIL.a]).trim();
    if (email) continue;                               // skip rows with email

    const nameKey = String(data[i][COL.NAMEKEY.a]).trim().toLowerCase();
    if (!nameKey) continue;

    const rawNormTs = data[i][COL.NORMTIMESTAMP.a];
    const tsMs      = rawNormTs instanceof Date
                        ? rawNormTs.getTime()
                        : new Date(rawNormTs).getTime();
    if (isNaN(tsMs)) continue;

    if (!candidatesByName[nameKey]) candidatesByName[nameKey] = [];
    candidatesByName[nameKey].push({ index: i, tsMs, normTs: rawNormTs });
  }

  // Compare every pair within each name group
  // Use a Set to track which array indices need flagging
  const toPair = [];   // [ { keptIndex, otherIndex } ] — kept = later timestamp

  for (const nameKey of Object.keys(candidatesByName)) {
    const group = candidatesByName[nameKey];
    if (group.length < 2) continue;

    // O(n²) over the group — group size is almost always 2–3 rows
    for (let a = 0; a < group.length; a++) {
      for (let b = a + 1; b < group.length; b++) {
        const diff = Math.abs(group[a].tsMs - group[b].tsMs);
        if (diff <= TEN_MINUTES_MS) {
          // kept = later timestamp
          const kept  = group[a].tsMs >= group[b].tsMs ? group[a] : group[b];
          const other = group[a].tsMs >= group[b].tsMs ? group[b] : group[a];
          toPair.push({ keptIndex: kept.index, otherIndex: other.index,
                        keptTs: kept.normTs,   otherTs: other.normTs });
        }
      }
    }
  }

  if (toPair.length === 0) return [];

  // Build updated N column — start from current values, set flag on both sides
  const newN = data.map(row => [row[COL.DUPNAMETIME.a]]);

  const logRows = [];

  for (const pair of toPair) {
    newN[pair.keptIndex]  = ["DUP-NAME-TIME"];
    newN[pair.otherIndex] = ["DUP-NAME-TIME"];

    const keptRowNum  = pair.keptIndex  + 2;
    const otherRowNum = pair.otherIndex + 2;

    logRows.push(["", keptRowNum, otherRowNum, pair.keptTs, pair.otherTs]);
  }

  raw.getRange(2, COL.DUPNAMETIME.r, numRows, 1).setValues(newN);
  return logRows;
}

// ── 3. Build / refresh the Superseded Log sheet ───────────────────────────────

function buildSupersededLog(ss, emailLogRows, nameLogRows) {
  let logSheet = ss.getSheetByName("Superseded Log");
  if (!logSheet) {
    logSheet = ss.insertSheet("Superseded Log");
  } else {
    logSheet.clearContents();
  }

  const header = [["Email", "Kept Row #", "Superseded Row #",
                   "Kept Timestamp", "Superseded Timestamp", "Duplicate Type"]];

  // Tag each row with its type so the log is easy to filter
  const emailRows = emailLogRows.map(r => [...r, "Email duplicate"]);
  const nameRows  = nameLogRows.map(r  => [...r, "Name+time duplicate"]);
  const allRows   = [...emailRows, ...nameRows];

  logSheet.getRange(1, 1, 1, 6).setValues(header);

  if (allRows.length > 0) {
    logSheet.getRange(2, 1, allRows.length, 6).setValues(allRows);
  }
}

// ── 4. Build / refresh the Final sheet ───────────────────────────────────────

function buildFinal(ss, raw) {
  const lastRow = raw.getLastRow();
  if (lastRow < 2) return;

  const numRows    = lastRow - 1;
  const sourceData = raw.getRange(2, 1, numRows, 6).getValues();           // A:F
  const opCols     = raw.getRange(2, COL.SUPERSEDED.r, numRows, 2).getValues(); // O:P

  const accepted = sourceData.filter((_, i) => {
    const superseded = String(opCols[i][0]).trim();
    const review     = String(opCols[i][1]).trim();
    return review === "OK" && superseded === "";
  });

  let final = ss.getSheetByName("Final");
  if (!final) {
    final = ss.insertSheet("Final");
  } else {
    final.clearContents();
  }

  const header = raw.getRange(1, 1, 1, 6).getValues();
  final.getRange(1, 1, 1, 6).setValues(header);

  if (accepted.length > 0) {
    final.getRange(2, 1, accepted.length, 6).setValues(accepted);
  }
}

// ── 5. Custom menu ────────────────────────────────────────────────────────────

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("Volunteer Data")
    .addItem("Refresh Final + Mark Superseded", "runCleanPipeline")
    .toUi();
}
```

---

### What changed

**`markNameDuplicates` is a new standalone function.** It only looks at rows where email is blank, groups them by NameKey, then does a pairwise comparison within each group. The O(n²) inner loop sounds worrying but each name group will realistically have 2–3 rows, so it's essentially O(n) across the whole sheet.

**NormTimestamp (col I) is used for the time comparison**, not the raw Timestamp in col A. This is intentional — your formula-cleaned timestamps in I are more reliably parsed than the raw mixed-format values in A, so the ±10-minute window will be accurate.

**Both rows in a name-duplicate pair get flagged.** Unlike the email logic where only the older row is marked SUPERSEDED, here neither row is authoritative — both get `DUP-NAME-TIME` in col N and both land in the log. The "kept" row in the log is simply whichever has the later timestamp, giving you a consistent reference point for review.

**The log grew a sixth column, "Duplicate Type"**, with values `Email duplicate` or `Name+time duplicate`. This makes the log filterable if you end up with a mix of both kinds. The column count change is handled inside `buildSupersededLog`, so the rest of the script doesn't need to know about it.

**`markSuperseded` now returns its log rows** rather than writing the log itself, and `buildSupersededLog` is split out as its own function that receives both sets of rows and writes them together. This keeps each function responsible for one thing and makes it straightforward to add more duplicate-detection types later if you need them.
